// Hoxi command sandbox overlay.
// Mirrors Kilo Code's per-tool OS confinement within upstream OpenCode without
// forking it: shell commands run under the Seatbelt profile generated by
// internal/sandbox, and file-writing tools are confined to the session
// workspace. Tools whose effects cannot be intercepted are denied while the
// sandbox is active instead of silently escaping it.
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { onDemandProfile, sandboxNote } from "./sandbox_route.mjs";
import { UTF8_SHELL_ENV, decodeWindowsOutputBuffer, ensureWindowsUTF8Runtime, repairWindowsMojibake } from "./windows_utf8.mjs";

const executable = "/usr/bin/sandbox-exec";

ensureWindowsUTF8Runtime();

function hash(value) {
  return createHash("sha256").update(value).digest("hex");
}

function snapshot(sessionID) {
  const root = process.env.HOXI_SANDBOX_ROOT;
  if (!root || !sessionID) return undefined;
  try {
    const raw = fs.readFileSync(path.join(root, hash(sessionID) + ".json"), "utf8");
    const value = JSON.parse(raw);
    if (!value || value.enabled !== true) return undefined;
    if (typeof value.profilePath !== "string" || typeof value.workspace !== "string") return undefined;
    if (!fs.existsSync(value.profilePath)) return undefined;
    return value;
  } catch {
    return undefined;
  }
}

function quote(value) {
  return `'${String(value).replaceAll("'", `'\\''`)}'`;
}

function inside(target, root) {
  if (process.platform === "win32") {
    target = target.toLowerCase();
    root = root.toLowerCase();
  }
  if (target === root) return true;
  return target.startsWith(root.endsWith(path.sep) ? root : root + path.sep);
}

function resolveTarget(value, workspace) {
  if (typeof value !== "string" || value.trim() === "") return undefined;
  let target = value.trim();
  if (target.startsWith("~")) target = path.join(process.env.HOME || process.env.USERPROFILE || os.homedir() || "", target.slice(1));
  target = path.isAbsolute(target) ? target : path.join(workspace, target);
  const resolved = path.resolve(target);
  let probe = resolved;
  const suffix = [];
  while (probe !== path.dirname(probe)) {
    try {
      const real = fs.realpathSync(probe);
      return suffix.length ? path.join(real, ...suffix.reverse()) : real;
    } catch {
      suffix.push(path.basename(probe));
      probe = path.dirname(probe);
    }
  }
  return resolved;
}

function canonicalWorkspace(value) {
  try {
    return fs.realpathSync(value);
  } catch {
    return path.resolve(value);
  }
}

function assertWritable(value, workspace) {
  const target = resolveTarget(value, workspace);
  if (!target) throw new Error("Hoxi sandbox requires an explicit file path");
  const parts = target.split(path.sep);
  if (parts.includes(".git")) throw new Error(`Hoxi sandbox denied write to git metadata: ${value}`);
  const root = canonicalWorkspace(workspace);
  if (!inside(target, root)) {
    throw new Error(`Hoxi sandbox denied write outside the session workspace: ${value}`);
  }
}

const FILE_WRITE_TOOLS = new Set(["write", "edit", "multiedit", "apply_patch"]);
const MUTATING_TOOLS = new Set(["write", "edit", "multiedit", "apply_patch", "patch"]);
const NETWORK_TOOLS = new Set(["webfetch", "websearch", "codesearch", "hoxi_browser", "hoxi_tools"]);
const POLLING_TOOLS = new Set([
  "todoread", "todowrite", "goal_report", "question", "wait", "wait_5_seconds",
  "command_status", "agent_status", "agent_wait", "bashoutput", "taskoutput", "taskget", "tasklist",
]);
const MUTATING_UI_ACTIONS = new Set([
  "click", "type", "navigate", "fill", "press", "key", "drag", "evaluate", "select",
]);
const DOOM_LOOP_THRESHOLD = 3;
const MAX_GUARDED_SESSIONS = 256;
const PATCH_PATH_RE = /^\*\*\* (?:Add File|Update File|Delete File|Move to):\s*(.+?)\s*$/gm;

function normalizeAction(args) {
  const raw = typeof args?.Action === "string" ? args.Action : typeof args?.action === "string" ? args.action : "";
  return raw.trim().replace(/^"+|"+$/g, "").trim().toLowerCase();
}

function isScrollToolCall(tool, args) {
  const name = String(tool || "").trim().toLowerCase();
  if (name === "scroll" || name.endsWith("_scroll") || name.endsWith(".scroll")) return true;
  const act = normalizeAction(args);
  if (act === "scroll" || act.startsWith("scroll_") || act.startsWith("scroll-")) return true;
  return false;
}

function isPollingToolCall(tool, args) {
  const name = String(tool || "").trim().toLowerCase();
  if (!name || POLLING_TOOLS.has(name)) return true;
  if (name === "manage_task") {
    const act = normalizeAction(args);
    return act === "status" || act === "list";
  }
  if (name === "manage_subagents") {
    return normalizeAction(args) === "list";
  }
  return false;
}

function isMutatingBashCommand(command) {
  if (typeof command !== "string" || command.trim() === "") return false;
  const scrubbed = command
    .replace(/(?:&|\d+)?>>?\s*\/dev\/null\b/g, " ")
    .replace(/\d*>&\d+/g, " ")
    .replace(/<<<?/g, " ");
  if (/(?:^|[^<>&])\d*>>?\|?\s*\S/.test(scrubbed)) return true;
  if (/\bsed\b[^\n;|&]*\s-(?:[a-zA-Z]*i|--in-place)\b/.test(command)) return true;
  if (/\bperl\b[^\n;|&]*\s-[a-zA-Z]*i/.test(command)) return true;
  if (/\b(?:tee|patch|cp|mv|rm|mkdir|rmdir|touch|truncate|install|dd|chmod|chown|ln)\b/.test(command)) return true;
  if (/\bgit\s+(?:apply|am|checkout|restore|reset|clean|revert|cherry-pick|merge|rebase|stash|mv|rm)\b/.test(command)) return true;
  if (/\b(?:python3?|node|ruby|perl|php)\b[^\n]*\s-(?:c|e)\b/.test(command)) return true;
  if (/\b(?:python3?|node|ruby|perl|php|sh|bash|zsh)\b[^\n]*<</.test(command)) return true;
  return false;
}

function isMutatingToolCall(tool, args, cleanBashCommand) {
  const name = String(tool || "").trim().toLowerCase();
  if (MUTATING_TOOLS.has(name)) return true;
  if (name === "bash") return isMutatingBashCommand(cleanBashCommand ?? args?.command);
  if (name === "hoxi_browser" || name === "hoxi_computer") return MUTATING_UI_ACTIONS.has(normalizeAction(args));
  return false;
}

function readFileSignature(filePath) {
  if (!filePath) return undefined;
  try {
    const st = fs.statSync(filePath);
    if (!st.isFile()) return `dir:${st.mtimeMs}`;
    if (st.size <= 4 * 1024 * 1024) return hash(fs.readFileSync(filePath));
    return `${st.size}:${st.mtimeMs}:${st.ctimeMs}`;
  } catch {
    return "missing";
  }
}

function resolveToolFileTarget(args, workspace) {
  const raw = args?.filePath ?? args?.path ?? args?.file ?? args?.target_file ?? args?.AbsolutePath ?? args?.Path;
  if (typeof raw !== "string" || raw.trim() === "") return undefined;
  return resolveTarget(raw, workspace || args?.workdir || process.cwd());
}

function recordBashCandidateFiles(state, cleanBashCommand, workspace, workdir) {
  if (typeof cleanBashCommand !== "string" || state.fileSignatures.size >= 64) return;
  const baseDir = workdir || workspace || process.cwd();
  const tokens = cleanBashCommand.match(/(?:[^\s"';|&<>()`]+|"[^"\n]*"|'[^'\n]*')+/g) || [];
  for (const raw of tokens) {
    if (state.fileSignatures.size >= 64) break;
    const token = raw.replace(/^['"]+|['"]+$/g, "").trim();
    if (!token || token.startsWith("-") || token.startsWith("$") || token === "/dev/null") continue;
    if (!token.includes("/") && !token.includes(".")) continue;
    const resolved = resolveTarget(token, baseDir);
    if (resolved && !state.fileSignatures.has(resolved)) state.fileSignatures.set(resolved, readFileSignature(resolved));
  }
}

function hasTrackedFileChanged(state, targetFile) {
  let changed = false;
  for (const [trackedPath, prevSig] of state.fileSignatures) {
    const curSig = readFileSignature(trackedPath);
    if (curSig !== prevSig) {
      state.fileSignatures.set(trackedPath, curSig);
      changed = true;
    }
  }
  if (targetFile && !state.fileSignatures.has(targetFile) && state.fileSignatures.size < 64) {
    state.fileSignatures.set(targetFile, readFileSignature(targetFile));
  }
  return changed;
}

function canonicalizeValue(value) {
  if (Array.isArray(value)) return value.map(canonicalizeValue);
  if (value && typeof value === "object") {
    const out = {};
    for (const key of Object.keys(value).sort()) out[key] = canonicalizeValue(value[key]);
    return out;
  }
  return value;
}

function toolCallFingerprint(tool, args, cleanBashCommand) {
  const name = String(tool || "").trim();
  if (name === "bash" && typeof cleanBashCommand === "string") {
    const workdir = typeof args?.workdir === "string" ? args.workdir.trim() : "";
    return hash(`bash\0${workdir}\0${cleanBashCommand.trim()}`);
  }
  return hash(`${name}\0${JSON.stringify(canonicalizeValue(args ?? null))}`);
}

function ensureSessionGuard(turnGuards, sessionID) {
  let state = turnGuards.get(sessionID);
  if (!state) {
    if (turnGuards.size >= MAX_GUARDED_SESSIONS) {
      const oldest = turnGuards.keys().next().value;
      if (oldest !== undefined) turnGuards.delete(oldest);
    }
    state = { turnID: "", recent: [], sinceEdit: new Map(), fileSignatures: new Map() };
    turnGuards.set(sessionID, state);
  }
  return state;
}

function observeToolCall(turnGuards, input, args, cleanBashCommand, workspace) {
  const sessionID = typeof input?.sessionID === "string" ? input.sessionID.trim() : "";
  const tool = typeof input?.tool === "string" ? input.tool.trim() : "";
  if (!sessionID || !tool || isPollingToolCall(tool, args)) return;
  const state = ensureSessionGuard(turnGuards, sessionID);
  if (isScrollToolCall(tool, args)) {
    state.recent = [];
    state.sinceEdit.clear();
    return;
  }
  const targetFile = resolveToolFileTarget(args, workspace);
  if (hasTrackedFileChanged(state, targetFile)) {
    state.recent = [];
    state.sinceEdit.clear();
  }
  if (tool.toLowerCase() === "bash") recordBashCandidateFiles(state, cleanBashCommand, workspace, args?.workdir);
  const fp = toolCallFingerprint(tool, args, cleanBashCommand);
  state.recent.push(fp);
  if (state.recent.length > DOOM_LOOP_THRESHOLD) state.recent.shift();
  const consecutiveRepeat = state.recent.length >= DOOM_LOOP_THRESHOLD && state.recent.every((item) => item === fp);
  let noEditRepeat = false;
  if (isMutatingToolCall(tool, args, cleanBashCommand)) {
    state.sinceEdit = new Map([[fp, 1]]);
  } else {
    const count = (state.sinceEdit.get(fp) || 0) + 1;
    state.sinceEdit.set(fp, count);
    noEditRepeat = count >= DOOM_LOOP_THRESHOLD;
  }
  if (consecutiveRepeat || noEditRepeat) {
    throw new Error(
      `Hoxi stopped a repeated tool call: ${tool} was called ${DOOM_LOOP_THRESHOLD} times with identical input in the same turn without changes. Do not repeat the same tool call; use the output already returned or try a different approach.`
    );
  }
}

function syncTurnFromMessages(turnGuards, messages) {
  if (!Array.isArray(messages)) return;
  let sessionID = "", lastUserMessageID = "";
  for (const message of messages) {
    const info = message?.info;
    if (!info || typeof info !== "object") continue;
    if (typeof info.sessionID === "string" && info.sessionID) sessionID = info.sessionID;
    if (info.role === "user" && typeof info.id === "string" && info.id && !info.id.startsWith("msg_u_recover_")) {
      lastUserMessageID = info.id;
    }
  }
  if (!sessionID || !lastUserMessageID) return;
  const state = turnGuards.get(sessionID);
  if (state && state.turnID !== lastUserMessageID) {
    state.turnID = lastUserMessageID;
    state.recent = [];
    state.sinceEdit.clear();
    state.fileSignatures.clear();
  }
}

function patchTargets(args) {
  const text = args.patchText ?? args.patch ?? args.input;
  return typeof text === "string" ? Array.from(text.matchAll(PATCH_PATH_RE), (m) => m[1]) : [];
}

function command(snapshot, input) {
  if (snapshot.network === "deny" && NETWORK_TOOLS.has(input.tool)) {
    throw new Error(`Hoxi sandbox denied network tool '${input.tool}' (sandbox network mode: deny)`);
  }
  if (input.tool === "bash" || FILE_WRITE_TOOLS.has(input.tool)) return true;
  if (["read", "grep", "glob", "list", "lsp", "todowrite", "todoread", "goal_report", "skill", "question", "hoxi_code_index", "hoxi_computer"].includes(input.tool)) return true;
  if (input.tool.startsWith("hoxi_memory_")) return true;
  if (snapshot.network === "allow" && NETWORK_TOOLS.has(input.tool)) return true;
  throw new Error(`Hoxi sandbox cannot confine tool '${input.tool}'; disable the sandbox to use it`);
}

// stopMarker tags every bash command with its engine session and tool call so
// Hoxi can stop exactly one command inside the shared `opencode serve` daemon.
// macOS hides other processes' environments, so the tag has to live in the
// command line itself; it is a shell comment and never affects execution.
const STOP_MARKER_PREFIX = "# hoxi-stop:";
const LEADING_STOP_MARKER_RE = /^[ \t]*# hoxi-stop:[^\n]*(?:\n|$)/;
const LEADING_LINE_RE = /^[ \t]*([^\n]*)(?:\n|$)/;

// STOP_TRAP follows the tag. OpenCode's bash tool only returns early when the
// shell exits with a code; a shell killed by a signal leaves the tool waiting
// for its full timeout. A stop therefore sends the shell SIGUSR1 and only
// terminates what it runs, and this trap prints the stop notice and exits 130
// once that command is gone, so the tool returns at once and the model reads
// that the user stopped it. The EXIT trap keeps sh and bash from exec-ing the
// last command in place of the shell, which would drop the tag and the trap.
// It must match openCodeStopTrap in internal/runner exactly.
const STOP_TRAP = String.raw`trap 'printf "\n[Command stopped by user]\n"; exit 130' USR1; trap : EXIT`;

// The trap is POSIX shell syntax; Windows shells and PowerShell cannot run it.
function trapSupported() {
  if (process.platform === "win32") return false;
  const shell = path.basename(process.env.SHELL || "").toLowerCase();
  return !shell.startsWith("pwsh") && !shell.startsWith("powershell");
}

function stopMarker(input) {
  if (typeof input?.sessionID !== "string" || typeof input?.callID !== "string") return undefined;
  if (!input.sessionID || !input.callID) return undefined;
  return `${STOP_MARKER_PREFIX}${input.sessionID}:${input.callID}`;
}

// stripStopMarkers drops every leading `# hoxi-stop:` line, the stop trap, and
// any outer `sandbox-exec` wrapper added on a prior step or echoed by a model.
// Tag lines are shell comments and the trap only matters for a stop, so this
// never changes what the command does; later lines are left alone because they
// may sit inside a heredoc or a quoted string. Not exported: OpenCode loads
// every export of a plugin module as a plugin.
const SANDBOX_WRAP_RE =
  /^(?:'[^']*\/sandbox-exec'|\/usr\/bin\/sandbox-exec|sandbox-exec)\s+-f\s+(?:'[^']*'|\S+)\s+--\s+(?:\/bin\/sh|sh)\s+-c\s+'((?:[^']|'\\'')*)'$/;

function stripStopMarkers(command) {
  if (typeof command !== "string") return command;
  let rest = command;
  for (let depth = 0; depth < 16; depth++) {
    const match = LEADING_STOP_MARKER_RE.exec(rest);
    if (match) {
      rest = rest.slice(match[0].length);
      continue;
    }
    const line = LEADING_LINE_RE.exec(rest);
    const trimmedLine = line ? line[1].trimEnd() : "";
    if (line && (trimmedLine === STOP_TRAP || trimmedLine === "trap : EXIT")) {
      rest = rest.slice(line[0].length);
      continue;
    }
    const wrapped = SANDBOX_WRAP_RE.exec(rest.trim());
    if (wrapped) {
      rest = wrapped[1].replace(/'\\''/g, "'");
      continue;
    }
    return rest;
  }
  return rest;
}

// OpenCode persists the tagged command as the tool input while the tool runs
// (`ctx.metadata` writes `args`), and completing the call re-reads that stored
// part, so the tag cannot be undone from `tool.execute.after`. Left alone, the
// model reads it back on later turns and starts writing its own tags with
// invented call IDs. cleanHistory strips it from bash inputs right before
// OpenCode serializes the history for the model, which also covers failed or
// rejected calls and history written before this fix. Parts are replaced, not
// mutated, so nothing leaks back into OpenCode's own state.
function cleanHistory(messages) {
  if (!Array.isArray(messages)) return;
  for (const message of messages) {
    const parts = message?.parts;
    if (!Array.isArray(parts)) continue;
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      if (part?.type !== "tool" || part.tool !== "bash") continue;
      const command = part.state?.input?.command;
      if (typeof command !== "string") continue;
      const clean = stripStopMarkers(command);
      if (clean === command) continue;
      parts[i] = { ...part, state: { ...part.state, input: { ...part.state.input, command: clean } } };
    }
  }
}

// OpenCode creates the plugin once per project directory and passes it in.
const HoxiSandboxPlugin = async (ctx) => {
  const turnGuards = new Map();
  const directory = typeof ctx?.directory === "string" ? ctx.directory : undefined;
  // Bash calls wrapped on demand, so their output can explain a sandbox denial.
  const onDemandCalls = new Set();
  return {
    "shell.env": async (_input, output) => {
      if (!output || typeof output.env !== "object" || !output.env) return;
      for (const [k, v] of Object.entries(UTF8_SHELL_ENV)) {
        if (!output.env[k]) output.env[k] = process.env[k] || v;
      }
      if (process.platform === "win32" && process.env.BASH_ENV && !output.env.BASH_ENV) {
        output.env.BASH_ENV = process.env.BASH_ENV;
      }
    },
    "tool.execute.before": async (input, output) => {
      const args = output?.args;
      const isBash = input?.tool === "bash" && args && typeof args === "object" && typeof args.command === "string";
      // The model may echo tags it saw in old history; only the tag added below
      // may reach the shell, so a stop never targets an invented call.
      const clean = isBash ? stripStopMarkers(args.command) : undefined;
      let final = clean;
      // Wrap in the sandbox first, then tag the final command: the tag must stay
      // the first line of what actually runs, so a stop can find this exact
      // process and the UI can strip it back to the user's command.
      const value = isBash || (input?.tool !== "bash" && output?.args) ? snapshot(input?.sessionID) : undefined;
      if (value) {
        if (!command(value, input)) return;
        if (isBash) {
          if (clean.trim() === "") throw new Error("Hoxi sandbox requires a non-empty shell command");
          final = `${quote(executable)} -f ${quote(value.profilePath)} -- /bin/sh -c ${quote(clean)}`;
        } else if (input.tool === "apply_patch") {
          const targets = patchTargets(args);
          if (targets.length === 0) throw new Error("Hoxi sandbox could not read the patch file paths");
          for (const target of targets) assertWritable(target, value.workspace);
        } else if (FILE_WRITE_TOOLS.has(input.tool)) {
          const target =
            args.filePath ?? args.path ?? args.file ?? args.target_file ?? args.AbsolutePath ?? args.Path;
          assertWritable(target, value.workspace);
        }
      } else if (isBash && clean.trim() !== "") {
        // No session sandbox: Hoxi may still confine a command it cannot read
        // instead of asking the user about it.
        const profile = await onDemandProfile({ sessionID: input?.sessionID, directory, command: clean });
        if (profile) {
          final = `${quote(executable)} -f ${quote(profile)} -- /bin/sh -c ${quote(clean)}`;
          if (onDemandCalls.size > 512) onDemandCalls.clear();
          if (typeof input?.callID === "string") onDemandCalls.add(input.callID);
        }
      }
      observeToolCall(turnGuards, input, args, clean, value?.workspace);
      if (!isBash) return;
      const tag = stopMarker(input);
      if (!tag) args.command = final;
      else if (trapSupported()) args.command = `${tag}\n${STOP_TRAP}\n${final}`;
      else args.command = `${tag}\n${final}`;
    },
    "tool.execute.after": async (input, output) => {
      if (!onDemandCalls.delete(input?.callID) || typeof output?.output !== "string") return;
      output.output += sandboxNote(output.output);
    },
    "experimental.chat.messages.transform": async (_input, output) => {
      syncTurnFromMessages(turnGuards, output?.messages);
      cleanHistory(output?.messages);
    },
    event: async ({ event }) => {
      const props = event?.properties || {};
      const type = event?.type;
      if (type === "session.deleted") {
        const sid = props.sessionID || props.info?.id;
        if (typeof sid === "string" && sid) turnGuards.delete(sid);
        return;
      }
      if ((type === "session.idle" || (type === "session.status" && props.status?.type === "idle")) && typeof props.sessionID === "string" && props.sessionID) {
        turnGuards.delete(props.sessionID);
        return;
      }
      if (type === "message.updated" && props.info?.role === "user" && typeof props.info?.sessionID === "string" && typeof props.info?.id === "string" && !props.info.id.startsWith("msg_u_recover_")) {
        const state = turnGuards.get(props.info.sessionID);
        if (state && state.turnID !== props.info.id) {
          state.turnID = props.info.id;
          state.recent = [];
          state.sinceEdit.clear();
          state.fileSignatures.clear();
        }
      }
    },
  };
};

